import Foundation

/// Ready-made programs in the library. Each one is generated by the offline
/// builder from a preset request, so it fits the user's chosen length.
struct ProgramTemplate: Identifiable {
    let id: String
    let name: String
    let tagline: String
    let description: String
    let level: Experience
    let category: Category
    let request: PlanRequest

    enum Category: String, CaseIterable, Identifiable {
        case strength = "Strength"
        case muscle = "Muscle"
        case fatLoss = "Fat Loss"
        case athletic = "Athletic"
        case home = "Home"
        case running = "Running"
        var id: String { rawValue }
    }

    var daysPerWeek: Int { request.daysPerWeek }
    var weeks: Int { request.weeks }

    static func make(_ id: String, _ name: String, _ tagline: String, _ description: String,
                     level: Experience, category: Category, preset: GoalPreset, weeks: Int, days: Int,
                     minutes: Int, equipment: Equipment, focus: Set<FocusArea> = []) -> ProgramTemplate {
        var request = PlanRequest()
        request.preset = preset
        request.experience = level
        request.weeks = weeks
        request.daysPerWeek = days
        request.sessionMinutes = minutes
        request.equipment = equipment
        request.focusAreas = focus
        return ProgramTemplate(id: id, name: name, tagline: tagline, description: description,
                               level: level, category: category, request: request)
    }

    static let all: [ProgramTemplate] = [
        make("starter-strength", "Starter Strength 3x", "Learn the big lifts and add weight every session",
             "Three full-body sessions a week built around squats, presses, rows and hinges. Weights go up whenever you hit all your reps, which is perfect for your first year of lifting.",
             level: .beginner, category: .strength, preset: .getStronger, weeks: 8, days: 3, minutes: 60, equipment: .fullGym),
        make("upper-lower-builder", "Upper/Lower Builder", "4 days of balanced size and strength",
             "Two upper and two lower days each week. Heavier compound work early in each session, higher-rep accessories after, with a deload every 4th week.",
             level: .intermediate, category: .muscle, preset: .buildMuscle, weeks: 12, days: 4, minutes: 70, equipment: .fullGym),
        make("ppl-6", "Push Pull Legs 6x", "High-frequency bodybuilding split",
             "Each muscle is trained twice a week across push, pull and leg days. High volume for experienced lifters chasing size.",
             level: .advanced, category: .muscle, preset: .buildMuscle, weeks: 12, days: 6, minutes: 75, equipment: .fullGym, focus: [.arms]),
        make("powerbuilder-5", "Power & Size 5x", "Strength wave loading plus bodybuilding volume",
             "Five days that mix heavy low-rep main lifts with hypertrophy accessories. Intensity rises over 3-week waves.",
             level: .intermediate, category: .strength, preset: .getStronger, weeks: 12, days: 5, minutes: 75, equipment: .fullGym),
        make("db-home", "Dumbbell Home Builder", "Build muscle with dumbbells and a bench",
             "A 4-day upper/lower plan designed for a home gym with adjustable dumbbells.",
             level: .intermediate, category: .home, preset: .buildMuscle, weeks: 8, days: 4, minutes: 50, equipment: .dumbbells),
        make("bodyweight-anywhere", "Bodyweight Anywhere", "No equipment, no excuses",
             "Three full-body bodyweight sessions with progressions from push-ups to archer push-ups and pistol work.",
             level: .beginner, category: .home, preset: .general, weeks: 6, days: 3, minutes: 40, equipment: .bodyweight, focus: [.core]),
        make("lean-conditioned", "Lean & Conditioned", "Lift, sweat and burn fat",
             "Four days of strength circuits plus conditioning finishers to keep muscle while dropping fat.",
             level: .intermediate, category: .fatLoss, preset: .loseFat, weeks: 8, days: 4, minutes: 45, equipment: .fullGym, focus: [.conditioning]),
        make("kb-shred", "Kettlebell Shred", "Swing, press and squat your way lean",
             "Three days of kettlebell strength and interval work. Great for small spaces.",
             level: .beginner, category: .fatLoss, preset: .loseFat, weeks: 6, days: 3, minutes: 35, equipment: .kettlebells, focus: [.conditioning]),
        make("vertical-jump", "Vertical Jump Accelerator", "Plyometrics plus strength for more pop",
             "Explosive jump training paired with heavy lower-body strength work, 4 days a week.",
             level: .intermediate, category: .athletic, preset: .jumpHigher, weeks: 8, days: 4, minutes: 60, equipment: .fullGym, focus: [.legs]),
        make("athlete-off-season", "Off-Season Athlete", "Speed, power and durability",
             "A field and court sport off-season plan: power, strength and conditioning across 4 days.",
             level: .advanced, category: .athletic, preset: .athletic, weeks: 10, days: 4, minutes: 70, equipment: .fullGym, focus: [.conditioning]),
        make("5k-builder", "5K Speed Builder", "Run faster with intervals, tempo and strength",
             "Easy, interval and tempo runs alternate with short strength sessions to make you faster and harder to injure.",
             level: .beginner, category: .running, preset: .runFaster, weeks: 8, days: 4, minutes: 45, equipment: .bodyweight),
    ]
}
